JOIN irms_purchase_requisitions p
  ON p.pr_no = v.pr_no AND p.pr_line = v.pr_line AND p.deleted_at IS NULL
ON CONFLICT (purchase_requisition_id, update_date) DO NOTHING;

-- ---------- Sinkronkan status terakhir ----------
-- current_status adalah salinan entri riwayat terbaru; diisi di sini supaya
-- halaman daftar tidak perlu subquery per baris.
UPDATE irms_purchase_requisitions p
SET current_status      = s.status,
    current_status_date = s.update_date
FROM (
    SELECT DISTINCT ON (purchase_requisition_id)
           purchase_requisition_id, status, update_date
    FROM irms_pr_status_updates
    ORDER BY purchase_requisition_id, update_date DESC
) s
WHERE s.purchase_requisition_id = p.id
  AND p.deleted_at IS NULL;
